'use strict';
// mysql2's command hierarchy: every subclass declares `start` with its own signature and return, so the base runner's `this.start`
// read cannot be one function type. A failed command replaces `start` by an own function.
class Command {
  constructor() {
    this.next = null;
    this.log = [];
  }
  execute(packet, connection) {
    if (!this.next) {
      this.next = this.start;
    }
    this.next = this.next(packet, connection);
    if (this.next) return false;
    return true;
  }
}
class A extends Command {
  start(packet, connection) {
    this.log.push('A.start ' + packet);
    return null;
  }
}
class B extends Command {
  start() {
    this.log.push('B.start');
    return null;
  }
}
class C extends Command {
  start(packet) {
    this.log.push('C.start ' + packet);
    return this.second;
  }
  second(packet) {
    this.log.push('C.second');
    return null;
  }
}
class D extends Command {
  start(packet, connection, extra) {
    this.log.push('D.start ' + (extra === undefined));
    return null;
  }
}
/** @param {Command} c */
function go(c, failed) {
  if (failed) {
    c.start = function () {
      c.log.push('override ran');
      return null;
    };
  }
  while (!c.execute(7, null));
  return c.log.join('|');
}
function run(kind, failed) {
  if (kind === 0) return go(new A(), failed);
  if (kind === 1) return go(new B(), failed);
  if (kind === 2) return go(new C(), failed);
  return go(new D(), failed);
}
module.exports = { run };
